            t.stale();
            sh_kk = @min(@as(usize, 512), 127 / r); // n_comp_end = (start + n) / ratio at a cold start 0
        };
        const n: usize = 127;
        const kk = sh_kk.?;
        if (kk % 16 != 0 and n > 16) {
            if (t.reusable(n, kk)) reuses += 1 else {
                t.held(n, kk);
                pads += 1;
            }
        }
    }
    try std.testing.expectEqual(@as(usize, 8), pads); // one pad per indexer selection
