test "hd ** -0.5 as the served build passes it" {
    try std.testing.expectEqual(@as(u32, 0x3d3504f3), @as(u32, @bitCast(scale(512))));
}

test "TF_DS_BF16_PARTIALS applies to two ranks and no 2D split (the series' parse is ops')" {
    try std.testing.expect(bf16PartialsWork(2, false) and bf16PartialsWork(4, false));
    try std.testing.expect(!bf16PartialsWork(1, false)); // one rank's gather copies its own partial: rounding is pure loss
    try std.testing.expect(!bf16PartialsWork(2, true) and !bf16PartialsWork(4, true)); // the 2D split's partials are per pair
}

test "TF_DS_PREFILL_GATHER_OVERLAP: two or more ranks, no 2D split, the series' parse" {
    try std.testing.expectEqualStrings("TF_DS_PREFILL_GATHER_OVERLAP", gather_side_env);
    try std.testing.expect(overlapWorks(2, false) and overlapWorks(4, false));
    try std.testing.expect(!overlapWorks(1, false)); // a lone rank's all-gather copies its own rows
    try std.testing.expect(!overlapWorks(2, true) and !overlapWorks(4, true)); // the 2D split's quarters post on the main stream
    try std.testing.expect(ops.onValue("1") and ops.onValue("on"));
    for ([_]?[]const u8{ null, "0", "off", "", "ON", "yes" }) |v| try std.testing.expect(!ops.onValue(v));
}

/// error.NotPortedYet with its site on stderr (a request that reaches a path the port lacks names it in the log).
fn notPorted(src: std.builtin.SourceLocation) error{NotPortedYet} {
    std.debug.print("{{\"not_ported\": \"{s}:{d}\"}}\n", .{ src.file, src.line });
    return error.NotPortedYet;
}

test "rankFault: a read this rank could not make ends the pair; other errors pass through" {
    for ([_]anyerror{ error.ReadFailed, error.EndOfFile, error.OutOfMemory, error.RowOutOfRange }) |err|
        try std.testing.expectEqual(@as(anyerror, error.EngramRankFault), rankFault(err));
    for ([_]anyerror{ error.EngramRankFault, error.TooManyRows, error.MissingEngramTable, error.BadSize, error.CommAborted, error.PairBroken, error.RingFailed }) |err|
        try std.testing.expectEqual(err, rankFault(err));
}

test "TF_DS_ENGRAM_METRICS: 0 turns the read timing off, everything else leaves it on" {
    for ([_]?[]const u8{ null, "", "1", "2", "on", "true", " 1", "1 " }) |v| try std.testing.expect(metricsEnabled(v));
    try std.testing.expect(!metricsEnabled("0"));
}

